const HeaderLogo = React.memo(() => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <div className="flex items-stretch  lg:gap-10 grow">
      {/* Mobile: Hamburger menu before logo */}
      <div className="lg:hidden flex items-center">
        <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
          <SheetTrigger asChild>
            <Button variant="ghost" size="icon" className="text-[var(--ariome-text-muted)] hover:bg-[var(--ariome-surface-hover)] hover:text-[var(--ariome-text)] lg:hidden">
              <Menu className="h-6 w-6" />
              <span className="sr-only">Toggle menu</span>
            </Button>
          </SheetTrigger>
          <SheetContent side="left" className="w-[300px] border-[var(--ariome-border)] bg-[var(--ariome-bg-elevated)] text-[var(--ariome-text)] sm:w-[400px]">
            <div className="flex flex-col">
              <Link 
                href="/home" 
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Home className="h-5 w-5" />
                <span className="font-medium">Home</span>
              </Link>
              <Link
                href="/explore"
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Search className="h-5 w-5" />
                <span className="font-medium">Explore</span>
              </Link>
              <Link
                href="/practice"
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Sparkles className="h-5 w-5" />
                <span className="font-medium">Practice</span>
              </Link>
              <Link
                href="/journal"
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <BookOpen className="h-5 w-5" />
                <span className="font-medium">Journal</span>
              </Link>
              <Link
                href="/circles"
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Users className="h-5 w-5" />
                <span className="font-medium">Circles</span>
              </Link>
              {isAuthenticated() && (
              <Link 
                href="/my-events" 
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <Calendar className="h-5 w-5" />
                <span className="font-medium">My Events</span>
              </Link>
              )}
              <Link 
                href="/membership"
                className="ariome-nav-pill flex w-full items-center gap-3 !rounded-lg !px-3"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                <CreditCard className="h-5 w-5" />
                <span className="font-medium">Membership</span>
              </Link>
            </div>
          </SheetContent>
        </Sheet>
      </div>

      {/* Logo - positioned after hamburger menu on mobile */}
      <div className="ml-2 flex shrink-0 items-center gap-2.5 lg:ml-5">
        <Link
          href="/home"
          aria-label="Ariome home"
          className="flex items-center rounded-sm outline-none ring-offset-2 focus-visible:ring-2 focus-visible:ring-teal-500/40"
        >
          <AriomeLogo />
        </Link>
      </div>

      <ElegantNav className="ml-4" />
    </div>
  );
});

HeaderLogo.displayName = 'HeaderLogo';

export { HeaderLogo };
